pub fn get_windows_catalog() -> Vec<Arc<dyn Tool>> {
    get_windows_catalog_with_sandbox(Arc::new(PathSandbox::new(
        vec![std::path::PathBuf::from(".")],
        vec![],
    )))
}

pub fn get_windows_catalog_with_sandbox(sandbox: Arc<PathSandbox>) -> Vec<Arc<dyn Tool>> {
    let mut tools: Vec<Arc<dyn Tool>> = Vec::with_capacity(1100);
    for cat in WINDOWS_CATEGORIES {
        for action in cat.actions {
            let canonical_id = format!("windows.{}.{}", cat.name, action.subaction);
            let mut properties = serde_json::Map::new();
            let mut required = Vec::new();
            for param in action.params {
                let mut prop = serde_json::Map::new();
                prop.insert(
                    "type".to_string(),
                    serde_json::Value::String(param.param_type.to_string()),
                );
                prop.insert(
                    "description".to_string(),
                    serde_json::Value::String(param.description.to_string()),
                );
                properties.insert(param.name.to_string(), serde_json::Value::Object(prop));
                if param.required {
                    required.push(serde_json::Value::String(param.name.to_string()));
                }
            }
            let mut schema = serde_json::Map::new();
            schema.insert(
                "type".to_string(),
                serde_json::Value::String("object".to_string()),
            );
            schema.insert(
                "properties".to_string(),
                serde_json::Value::Object(properties),
            );
            if !required.is_empty() {
                schema.insert("required".to_string(), serde_json::Value::Array(required));
            }

            let meta = ToolMetadata {
                canonical_id,
                domain_category: cat.name.to_string(),
                target_os: TargetOs::Windows,
                description: action.description.to_string(),
                parameters_schema: serde_json::Value::Object(schema),
                permission_tier: action.tier,
                latency_class: action.latency,
                reversibility: action.reversibility,
                adapter_cmd: action.adapter_cmd.to_string(),
                adapter_args: action.adapter_args.to_string(),
            };

            tools.push(Arc::new(EcosystemTool::with_sandbox(meta, sandbox.clone())));
        }
    }
    tools
}
